import { useState } from "react";
import { FiRefreshCw } from "react-icons/fi";
import { WALLET_PROVIDER_CHANGED_EVENT } from "../contract/contractClients";
import { getWalletErrorMessage } from "../utils/walletErrors";

export default function WalletConnectionStatus({ cont, access }) {
    const [busy, setBusy] = useState(false);
    const [message, setMessage] = useState("");
    if (access.canAnswerQuiz) return null;

    const connect = async () => {
        setBusy(true);
        setMessage("");
        try {
            const accounts = await cont.request_wallet_access();
            if (!Array.isArray(accounts) || !accounts.length) throw new Error("wallet_not_connected");
            window.dispatchEvent(new CustomEvent(WALLET_PROVIDER_CHANGED_EVENT, { detail: { type: "connected", accounts } }));
            setMessage("接続しました。登録状況を確認しています。");
        } catch (error) {
            setMessage(getWalletErrorMessage(error) || "ウォレット接続を確認できません。接続先のサイトと通信状態を確認して再試行してください。");
        } finally { setBusy(false); }
    };

    return <section aria-label="ウォレット接続状況" style={{ padding: "16px 0", marginBottom: 16, borderBottom: "1px solid var(--border-color, #555)", overflowWrap: "anywhere" }}>
        <h3 className="heading-md">{access.isConnected ? "アカウントの登録確認" : "ウォレット未接続"}</h3>
        <p>{access.isConnected ? "このアドレスの回答権限を確認できません。教員に登録済みのウォレットか確認してください。" : "回答の提出にはウォレット接続が必要です。Firefox・Chrome・Edgeでは MetaMask 拡張機能の有効化と、このサイトへのアクセス許可を確認してください。スマートフォンは MetaMask アプリ内のブラウザーで開いてください。"}</p>
        {access.address && <p>{access.address}</p>}
        <div style={{ display: "flex", flexWrap: "wrap", gap: 12, alignItems: "center" }}>
            <button type="button" className="btn-primary-custom" disabled={busy} onClick={connect}><FiRefreshCw aria-hidden="true" /> {busy ? "接続確認中..." : "ウォレットを接続・再確認"}</button>
            <a href="https://support.metamask.io/third-party-platforms-and-dapps/i-cant-connect-metamask-extension-to-a-dapp-/" target="_blank" rel="noopener noreferrer">MetaMask の接続トラブルを確認</a>
        </div>
        {message && <p role="status" style={{ marginTop: 12 }}>{message}</p>}
    </section>;
}
