export function getWalletErrorMessage(error) {
    const errors = [];
    const seen = new Set();
    const visit = (item) => {
        if (!item || typeof item !== "object" || seen.has(item)) return;
        seen.add(item);
        errors.push(item);
        visit(item.cause);
        visit(item.data?.originalError);
        visit(item.error);
    };
    visit(error);
    const codes = errors.map((item) => Number(item.code));
    const message = errors.map((item) => `${item.shortMessage || ""} ${item.message || ""}`).join(" ").toLowerCase();
    if (codes.includes(4001) || message.includes("user rejected")) return "ウォレットで操作がキャンセルされました。";
    if (codes.includes(-32002) || message.includes("already pending")) return "ウォレットの確認待ちです。MetaMask の拡張機能またはアプリを開き、保留中の接続・署名を確認してください。";
    if (message.includes("ethereum_not_found") || message.includes("metamask_not_found")) return "ウォレットを検出できません。PCでは MetaMask 拡張機能とこのサイトへのアクセス許可を確認してください。スマートフォンでは MetaMask アプリ内のブラウザーで開いてください。";
    if (message.includes("wallet_account_changed")) return "ウォレットのアカウントが変わりました。登録済みのアカウントを確認してから再送してください。";
    if (codes.includes(4100) || codes.includes(4900) || message.includes("wallet_not_connected")) return "ウォレットが未接続です。登録済みのアカウントで接続し直してください。";
    if (message.includes("answer_transaction_reverted")) return "回答の取引が失敗しました。提出は完了していません。締め切り・回答済み状態を確認して再送してください。";
    return "";
}
